# Generated by Selenium IDE
import pytest
import time
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC


class TestBerthScheduling:
    def setup_method(self, method):
        self.driver = webdriver.Chrome()
        self.driver.maximize_window()
        self.wait = WebDriverWait(self.driver, 10)

    def teardown_method(self, method):
        self.driver.quit()

    def test_berth_scheduling(self):
        # Authenticate as Port Berthing Administrator
        self.driver.get("https://portide.vercel.app/login")
        self.wait.until(EC.visibility_of_element_located((By.NAME, "email"))).send_keys("aleena302005@gmail.com")
        self.wait.until(EC.visibility_of_element_located((By.NAME, "password"))).send_keys("Aleena@2005")
        self.wait.until(EC.element_to_be_clickable((By.CSS_SELECTOR, "button[type='submit']"))).click()

        # Navigate to Berth Planning view
        self.driver.get("https://portide.vercel.app/berths")

        # Wait for terminal quayside berth layout to load
        berth_timeline = self.wait.until(
            EC.presence_of_element_located((By.CSS_SELECTOR, ".berth-timeline, .berth-grid"))
        )
        assert berth_timeline.is_displayed()

        # Open berth assignment dialog for pending arriving vessel
        assign_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'Assign Berth') or contains(., 'Schedule')]"))
        )
        assign_btn.click()

        # Confirm berth assignment and verify schedule synchronization
        confirm_btn = self.wait.until(
            EC.element_to_be_clickable((By.XPATH, "//button[contains(., 'Confirm') or contains(., 'Save')]"))
        )
        confirm_btn.click()
        self.wait.until(EC.presence_of_element_located((By.XPATH, "//*[contains(text(), 'Confirmed') or contains(text(), 'Reserved')]")))
        time.sleep(2)
